updates = {}
for name, spec in EDITS.items():
    path = Path(name)
    original = path.read_bytes()
    assert hashlib.sha256(original).hexdigest() == spec["before"], f"Concurrent change: {name}"
    lines = original.decode().splitlines(keepends=True)
    for start, end, replacement in reversed(spec["edits"]):
        lines[start:end] = [replacement]
    result = "".join(lines).encode()
    assert hashlib.sha256(result).hexdigest() == spec["after"], f"Invalid patch: {name}"
    updates[path] = result
for path, result in updates.items():
    path.write_bytes(result)
print(f"Applied {len(updates)} verified source updates")
